std::pair<std::string, int> getMonthAndDay(int dayOfYear) {
    std::tm timeIn = {0, 0, 0,  // second, minute, hour
                      1, 0,  // 0-based month
                      100};  // year since 1900

    timeIn.tm_yday = dayOfYear - 1;  // tm_yday is 0-based

    std::mktime(&timeIn);

    std::string monthNames[] = {"January", "February", "March", "April", "May", "June",
                                "July", "August", "September", "October", "November", "December"};

    return {monthNames[timeIn.tm_mon], timeIn.tm_mday};
}

int main() {
    int dayOfYear;
    std::cout << "Enter the day of the year (1-365): ";
    std::cin >> dayOfYear;

    if (dayOfYear < 1 || dayOfYear > 365) {
        std::cerr << "Invalid day of the year.\n";
        return 1;
    }

    auto result = getMonthAndDay(dayOfYear);

    std::cout << "Month: " << result.first << "\n";
    std::cout << "Day in month: " << result.second << "\n";

    return 0;
}

#include <iostream>
#include <string>

std::string findMonth(int index) {
    const int startingIndices[] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
    const char* monthNames[] = {"JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"};

    for (int i = 0; i < 12; ++i) {
        if (index >= startingIndices[i] && index < startingIndices[i + 1]) {
            return monthNames[i];
        }
    }

    return ""; // Handle out-of-range input
}

int findDay(const std::string& month, int index) {
    const int startingIndices[] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};

    for (int i = 0; i < 12; ++i) {
        if (month == findMonth(startingIndices[i])) {
            return index - startingIndices[i] + 1;
        }
    }

    return -1; // Handle invalid month input
}

int main() {
    int index;
    std::cout << "Enter the index (1-365): ";
    std::cin >> index;

    if (index < 1 || index > 365) {
        std::cerr << "Invalid index.\n";
        return 1;
    }

    std::string month = findMonth(index);
    int date = findDay(month, index);

    std::cout << "Month: " << month << "\n";
    std::cout << "Day in month: " << date << "\n";

    return 0;
}

