// Function prototype for finding minimum and maximum values in an array
void findMinMax(double[], double&, double&);

int main()
{
    // Initialize an array of doubles
    double list[ARRAY_SIZE] = {3.5, 1.6, -4.9, 2.5};

    // Initialize variables to hold minimum and maximum values
    double minimum = list[0];
    double maximum = list[0];

    // Call the function to find minimum and maximum values
    findMinMax(list, minimum, maximum);

    // Output the minimum and maximum values
    cout << "Minimum: " << minimum << endl;
    cout << "Maximum: " << maximum << endl;
    return 0;
}

// Function to find minimum and maximum values in an array
// Parameters:
//   list: Array of doubles
//   minimum: Reference to a double to store the minimum value found
//   maximum: Reference to a double to store the maximum value found
void findMinMax(double list[], double& minimum, double& maximum)
{
    // Iterate through the array starting from index 1
    for (int i = 1; i < ARRAY_SIZE; i++)
    {
        // Check if the current element is less than the current minimum
        if (list[i] < minimum) {
            // Update the minimum value if the condition is met
            minimum = list[i];
        }
        // Check if the current element is greater than the current maximum
        else if (list[i] > maximum)
        {
            // Update the maximum value if the condition is met
            maximum = list[i];
        }
    }
}

#include <iostream>

class Time {
private:
    int hour;
    int min;
    int sec;

    void normalizeTime() {
        min += sec / 60;
        sec %= 60;
        hour += min / 60;
        min %= 60;
    }

public:
    Time() : hour(0), min(0), sec(0) {}

    Time(int hour, int min, int sec) : hour(hour), min(min), sec(sec) {
        normalizeTime();
    }

    void setTime(int hour, int min, int sec) {
        this->hour = hour;
        this->min = min;
        this->sec = sec;
        normalizeTime();
    }

    void printTime() const {
        std::cout << hour << ":" << min << ":" << sec << "\n";
    }

    friend Time operator+(const Time &obj1, const Time &obj2);
    friend Time operator+(const Time &obj1, int secs);
    friend std::ostream &operator<<(std::ostream &out, const Time &obj);
};

Time operator+(const Time &obj1, const Time &obj2) {
    Time result;
    result.sec = obj1.sec + obj2.sec;
    result.min = obj1.min + obj2.min;
    result.hour = obj1.hour + obj2.hour;
    result.normalizeTime();
    return result;
}

Time operator+(const Time &obj1, int secs) {
    Time result = obj1;
    result.sec += secs;
    result.normalizeTime();
    return result;
}

std::ostream &operator<<(std::ostream &out, const Time &obj) {
    out << obj.hour << ":" << obj.min << ":" << obj.sec;
    return out;
}

int main() {
    Time t1(1, 30, 45);
    Time t2(0, 45, 15);

    Time t3 = t1 + t2;
    std::cout << "t1 + t2: " << t3 << std::endl;

    Time t4 = t1 + 1000;
    std::cout << "t1 + 1000 seconds: " << t4 << std::endl;

    return 0;
}

