// Searches for all possible substrings that can be formed by concatenating words from the word list within the target string
void findSubstrings(std::unordered_map<std::string, int>& substringCounts, std::unordered_map<std::string, int> wordList, 
                    const std::string& targetString, int startIndex, int wordLength, const std::string& currentSubstring = "");

// Displays all found substrings and their counts
void displaySubstrings(const std::unordered_map<std::string, int>& substringCounts);

int main() {
    std::unordered_map<std::string, int> wordFrequencyMap;
    std::unordered_map<std::string, int> substringCountMap;

    std::cout << "Enter target string: ";
    std::string targetString;
    std::cin >> targetString;

    std::cout << "Enter list of words (type 'END' to finish):\n";
    std::string word;
    while (std::cin >> word && word != "END") {
        wordFrequencyMap[word]++;
    }

    if (wordFrequencyMap.empty()) {
        std::cout << "Word list is empty.\n";
        return 0;
    }

    int wordLength = wordFrequencyMap.begin()->first.size();

    std::cout << "List of substrings:\n";
    findSubstrings(substringCountMap, wordFrequencyMap, targetString, 0, wordLength);

    if (substringCountMap.empty()) {
        std::cout << "No substrings found.\n";
    } else {
        displaySubstrings(substringCountMap);
    }
    return 0;
}

void findSubstrings(std::unordered_map<std::string, int>& substringCounts, std::unordered_map<std::string, int> wordList, 
                    const std::string& targetString, int startIndex, int wordLength, const std::string& currentSubstring) {
    if (startIndex + wordLength > targetString.size()) return;

    std::string foundWord = targetString.substr(startIndex, wordLength);
    if (wordList.find(foundWord) != wordList.end()) {
        std::string newSubstring = currentSubstring + foundWord;
        wordList[foundWord]--;
        if (wordList[foundWord] == 0) {
            wordList.erase(foundWord);
        }

        if (wordList.empty()) {
            substringCounts[newSubstring]++;
        } else {
            findSubstrings(substringCounts, wordList, targetString, startIndex + wordLength, wordLength, newSubstring);
        }
    }
}

void displaySubstrings(const std::unordered_map<std::string, int>& substringCounts) {
    for (const auto& pair : substringCounts) {
        std::cout << pair.first << " - Count: " << pair.second << '\n';
    }
}

TBuffer TBuffer::copy(QPoint& P1, QPoint& P2)
{
    TBuffer slice(mpHost);
    slice.clear();
    const int y = P1.y();
    int x = P1.x();
    if (y < 0 || y >= static_cast<int>(buffer.size())) {
        return slice;
    }

    // Ensure x starts within the valid range, and adjust P2.x() if it's out of bounds
    if (x < 0 || x >= static_cast<int>(buffer.at(y).size())) {
        x = 0; // Reset x to start of line if out of bounds
    }
    int P2x_corrected = std::min(P2.x(), static_cast<int>(buffer.at(y).size()) - 1); // Correct P2.x() to prevent out-of-bounds

    int oldLinkId{}, id{};
    for (; x <= P2x_corrected; ++x) { // Use corrected P2.x() in loop condition and allow x to start from corrected position
        const int linkId = buffer.at(y).at(x).linkIndex();
        if (linkId && (linkId != oldLinkId)) {
            id = slice.mLinkStore.addLinks(mLinkStore.getLinksConst(linkId), mLinkStore.getHintsConst(linkId), mpHost);
            oldLinkId = linkId;
        }

        if (!linkId) {
            id = 0;
        }
        const QString s(lineBuffer.at(y).at(x));
        slice.append(s, 0, 1, buffer.at(y).at(x).mFgColor, buffer.at(y).at(x).mBgColor, buffer.at(y).at(x).mFlags, id);
    }
    return slice;
}

// Function definition for _88MPH, which finds a path through charging stations considering battery constraints
stack<string> _88MPH(unordered_map<string, list<edge>> mapOfChargingStations, unordered_map<string, double> chargingStation, string startingLocation, double initialBattery){
    // Initialize an empty stack to store the path
    stack<string> stationPath;
    // Declare a string variable to store the name of the current station
    string stationName = "";

    // Initialize variables to store battery charge and other parameters
    double currentBattery = initialBattery;
    double decreaseBattery = 0.0;
    double currentDistance = 0.0;
    double charge = chargingStation[startingLocation];

    // If the initial battery is zero or negative, return an empty path
    if(currentBattery <= 0.0)
        return {};

    // Charge the battery based on the charging station's power
    currentBattery = currentBattery + charge;

    // If the battery charge exceeds 75.5, return an empty path
    if(currentBattery > 75.5)
        return {};

    // If the battery charge is between 62.5 and 75.5 (inclusive), push the starting location onto the path and return
    if(currentBattery >= 62.5 && currentBattery <= 75.5){
        stationPath.push(startingLocation);
        return stationPath;
    }

    // Iterate over neighbors of the starting location in the map of charging stations
    for(auto& neighbor : mapOfChargingStations[startingLocation]){
        // Extract neighbor's station name and distance
        stationName = neighbor.station;
        currentDistance = neighbor.distance;
        // Calculate battery decrease based on distance traveled
        decreaseBattery = currentDistance * 0.346;
        // Recursively call _88MPH function with updated parameters
        stationPath = _88MPH(mapOfChargingStations, chargingStation, stationName, currentBattery-decreaseBattery);

        // If a non-empty path is found, push the starting location onto the path and break the loop
        if(!stationPath.empty()){
            stationPath.push(startingLocation);
            break;
        }
    }

    // Return the resulting station path
    return stationPath;
}

stack<string> _88MPH(const unordered_map<string, list<edge>>& mapOfChargingStations, const unordered_map<string, double>& chargingStation, const string& startingLocation, double initialBattery) {
    // Initialize an empty stack to store the path
    stack<string> stationPath;

    // Check if initial battery is non-positive or starting location is invalid
    if (initialBattery <= 0.0 || chargingStation.find(startingLocation) == chargingStation.end())
        return stationPath; // Return empty stack

    // Calculate current battery charge including charge from the starting location
    double currentBattery = initialBattery + chargingStation.at(startingLocation);

    // Check if current battery exceeds maximum allowed charge
    if (currentBattery > 75.5)
        return stationPath; // Return empty stack

    // If battery charge is between 62.5 and 75.5 (inclusive), push the starting location onto the path and return
    if (currentBattery >= 62.5) {
        stationPath.push(startingLocation);
        return stationPath;
    }

    // Iterate over neighbors of the starting location in the map of charging stations
    for (const auto& neighbor : mapOfChargingStations.at(startingLocation)) {
        // Calculate battery decrease based on distance traveled
        double decreaseBattery = neighbor.distance * 0.346;
        // Recursively call _88MPH function with updated parameters
        stack<string> path = _88MPH(mapOfChargingStations, chargingStation, neighbor.station, currentBattery - decreaseBattery);

        // If a non-empty path is found, push the starting location onto the path and return
        if (!path.empty()) {
            path.push(startingLocation);
            return path;
        }
    }

    // Return empty stack if no valid path is found
    return stationPath;
}

