#include <iostream>
#include <vector>

void merge(std::vector<int>& array, int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;

    std::vector<int> leftArray(n1), rightArray(n2);

    for (int i = 0; i < n1; ++i)
        leftArray[i] = array[left + i];
    for (int j = 0; j < n2; ++j)
        rightArray[j] = array[mid + 1 + j];

    int i = 0, j = 0, k = left;

    while (i < n1 && j < n2) {
        if (leftArray[i] <= rightArray[j])
            array[k++] = leftArray[i++];
        else
            array[k++] = rightArray[j++];
    }

    while (i < n1)
        array[k++] = leftArray[i++];
    while (j < n2)
        array[k++] = rightArray[j++];
}

void mergeSort(std::vector<int>& array, int begin, int end) {
    if (begin < end) {
        int mid = begin + (end - begin) / 2;
        mergeSort(array, begin, mid);
        mergeSort(array, mid + 1, end);
        merge(array, begin, mid, end);
    }
}

void printArray(const std::vector<int>& array) {
    for (int num : array)
        std::cout << num << " ";
    std::cout << std::endl;
}

int main() {
    std::vector<int> arr = {12, 11, 13, 5, 6, 7};
    std::cout << "Given array is:\n";
    printArray(arr);

    mergeSort(arr, 0, arr.size() - 1);

    std::cout << "\nSorted array is:\n";
    printArray(arr);

    return 0;
}

#include <iostream>

using namespace std;

// Node structure to represent each element in the stack
struct Node
{
    int data;     // Data of the node
    Node *next;   // Pointer to the next node
};

// Stack structure to implement stack operations
struct Stack
{
    Node *top = nullptr;   // Pointer to the top of the stack

    /**
     * @brief Pushes a new element onto the stack.
     * 
     * @param data The data to be pushed onto the stack.
     */
    void push(int data);

    /**
     * @brief Pops the top element from the stack.
     * 
     * @return int The data of the popped element, or -1 if the stack is empty.
     */
    int pop();
};

void Stack::push(int data)
{
    // Create a new node
    Node *newNode = new Node;
    newNode->data = data;

    // Set the next pointer of the new node to the current top
    newNode->next = top;

    // Update the top pointer to the new node
    top = newNode;   
}

int Stack::pop()
{
    // Check if the stack is empty
    if (top == nullptr)
    {
        cout << "Stack is empty" << endl;
        return -1;
    }

    // Store the data of the top node
    int data = top->data;

    // Move the top pointer to the next node
    Node *temp = top;
    top = top->next;

    // Delete the original top node
    delete temp;

    return data;
}

int main()
{
    // Create a new stack object
    Stack s;

    // Push some elements onto the stack
    s.push(5);
    s.push(7);
    s.push(-3);

    // Pop and print elements from the stack
    cout << s.pop() << endl;
    s.push(9);
    while(s.top != nullptr)
        cout << s.pop() << endl;

    return 0;
}

#include <iostream>
using namespace std;

// Define a structure for a node in the queue
struct Node {
    int data;
    Node *next;
};

// Define a structure for the queue
struct Queue {
    Node *front = nullptr; // Initialize front pointer to nullptr
    Node *rear = nullptr;  // Initialize rear pointer to nullptr

    // Function to add an element to the queue
    void enqueue(int data);

    // Function to remove an element from the queue
    int dequeue();
};

// Function to add an element to the queue
void Queue::enqueue(int data) {
    // Create a new node
    Node *newNode = new Node;
    newNode->data = data;
    newNode->next = nullptr; // Set next pointer to nullptr

    // If the queue is empty, set both front and rear to the new node
    if (front == nullptr) {
        front = newNode;
        rear = newNode;
    } else {
        // Otherwise, add the new node to the rear and update rear pointer
        rear->next = newNode;
        rear = newNode;
    }
}

// Function to remove an element from the queue
int Queue::dequeue() {
    // If the queue is empty, print a message and return -1
    if (front == nullptr) {
        cout << "The Queue is empty" << endl;
        return -1;
    } else {
        // Otherwise, remove the front node and return its data
        Node *temp = front;
        int data = temp->data;
        front = front->next;
        delete temp;
        return data;
    }
}

int main() {
    Queue q; // Create a queue object

    // Enqueue some elements
    q.enqueue(5);
    q.enqueue(7);
    q.enqueue(-3);

    // Dequeue and print elements until the queue is empty
    cout << q.dequeue() << endl;
    q.enqueue(9);
    while (q.front != nullptr)
        cout << q.dequeue() << endl;

    return 0;
}

