void DescriptorPool::AddEntity(Entity* entity)
{
    auto device = m_pDevice->GetVkDevice();

    // Vérifiez si le pool actuel a suffisamment de place
    if (m_CurrentDescriptorCount >= m_MaxDescriptorCount) {
        // Le pool actuel n'a pas suffisamment de place, étendez-le
        ExtendDescriptorPool();
    }

    // Allouez un ensemble de descripteurs pour l'entité
    VkDescriptorSetAllocateInfo allocInfo{};
    allocInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    allocInfo.descriptorPool = m_DescriptorPool;
    allocInfo.descriptorSetCount = 1;
    allocInfo.pSetLayouts = &m_DescriptorSetLayout;

    if (vkAllocateDescriptorSets(device, &allocInfo, &entity->GetDescriptorSet()) != VK_SUCCESS) {
        throw std::runtime_error("failed to allocate descriptor sets!");
    }

    // Mettez à jour les descripteurs pour l'entité (comme vous le faites actuellement)
    UpdateDescriptors(entity);

    // Incrémentez le compteur de descripteurs actuel
    m_CurrentDescriptorCount++;
}

void DescriptorPool::ExtendDescriptorPool()
{
    // Doublez la taille du pool (vous pouvez ajuster cette stratégie en fonction de vos besoins)
    m_MaxDescriptorCount *= 2;

    // Créez un nouveau pool de descripteurs
    VkDescriptorPool newDescriptorPool;
    CreateDescriptorPool(newDescriptorPool, m_MaxDescriptorCount);

    // Transférez les descripteurs de l'ancien pool vers le nouveau
    TransferDescriptors(newDescriptorPool);

    // Détruisez l'ancien pool
    vkDestroyDescriptorPool(m_pDevice->GetVkDevice(), m_DescriptorPool, nullptr);

    // Remplacez l'ancien pool par le nouveau
    m_DescriptorPool = newDescriptorPool;
}

void DescriptorPool::CreateDescriptorPool(VkDescriptorPool& descriptorPool, u32 descriptorCount)
{
    std::array<VkDescriptorPoolSize, 2> poolSizes{};
    poolSizes[0].type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
    poolSizes[0].descriptorCount = descriptorCount;
    poolSizes[1].type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    poolSizes[1].descriptorCount = descriptorCount;

    VkDescriptorPoolCreateInfo poolInfo{};
    poolInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    poolInfo.flags = VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT;
    poolInfo.poolSizeCount = static_cast<u32>(poolSizes.size());
    poolInfo.pPoolSizes = poolSizes.data();
    poolInfo.maxSets = descriptorCount;

    if (vkCreateDescriptorPool(m_pDevice->GetVkDevice(), &poolInfo, nullptr, &descriptorPool) != VK_SUCCESS) {
        throw std::runtime_error("failed to create descriptor pool!");
    }
}

