char** hash_to_env_array(HashTable* ht) {
    int env_count = ht->count;
    char** env_array = malloc((env_count + 1) * sizeof(char*));

    int i = 0;
    for each entry in ht {
        env_array[i] = format("%s=%s", entry->key, entry->value); // This should concatenate key and value with '=' in between.
        i++;
    }
    env_array[i] = NULL;  // Null terminate the array.

    return env_array;
}

typedef struct s_env_table {
    t_env_var *table[TABLE_SIZE];
    int count;  // This will keep track of the number of environment variables.
} t_env_table;

char** hash_table_to_env_array(t_env_table* ht) {
    char** env_array = malloc((ht->count + 1) * sizeof(char*));
    if (!env_array) {
        // handle memory allocation error
        return NULL;
    }

    int index = 0;
    for (int i = 0; i < TABLE_SIZE; i++) {
        t_env_var* node = ht->table[i];
        while (node != NULL) {
            // Assuming you have a function to concatenate strings with a separator:
            env_array[index] = str_join_with_separator(node->key, "=", node->value);
            index++;
            node = node->next;
        }
    }
    env_array[ht->count] = NULL;

    return env_array;
}

