    else if (currentMillis - lastSW4Press >= 3000 && servoActivated) { // ตรวจสอบว่าผ่านไปเวลา 3 วินาทีและเซอร์โวถูกเปิด
      myservo.write(0);
      lastSW4Press = currentMillis; // อัปเดตเวลาที่ SW4 ถูกกดล่าสุด
