#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include "includes/rwlocks.h"
#include "includes/hashdb.h"

#define BUFFER_SIZE 255
#define HASH_TABLE_SIZE 10

/* Parser */

typedef struct line_t {

    char* command;
    char* param_one;
    char* param_two;

} line_t;

FILE* open_input_file();
FILE* open_output_file();
line_t parse_line(char* buffer);
void free_line(line_t line);
void* hash_table_thread_function(void* arg);

/* Threads */

typedef struct thread_args_t {

    hash_record_t** hash_table;
    rwlock_t* lock;
    FILE* in_fp;
    FILE* out_fp;

} thread_args_t;

pthread_t* allocate_threads(size_t num_threads);

pthread_mutex_t file_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Entry Point */

int main(void) {

    // Open input file for reading
    FILE* in_fp = open_input_file();

    // Create or open the output.txt file
    FILE* out_fp = open_output_file();

    // Create a empty hash table
    hash_record_t** hash_table = create_hash_table(HASH_TABLE_SIZE);

    // Create a buffer to store a line read in from file
    char buffer[BUFFER_SIZE];

    // Read in the number of threads needed from the input file
    fgets(buffer, BUFFER_SIZE, in_fp);
    line_t line = parse_line(buffer);
    uint32_t num_threads = atoi(line.param_one);
    free_line(line);

    fprintf(out_fp, "Running %d threads\n", num_threads);

    // Create hash table lock to protect reads and writes
    rwlock_t* lock = rwlock_init();

    // Create thread args needed to run
    thread_args_t thread_args = {.hash_table = hash_table, .in_fp = in_fp, .out_fp = out_fp, .lock = lock};

    // Allocate space for the pthreads
    pthread_t* threads = allocate_threads(num_threads);

    // Run the threads
    for(uint32_t i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, hash_table_thread_function, (void*)&thread_args);
    }

    // Wait for threads to finish
    for(uint32_t i = 0; i < num_threads; i++) {
        pthread_join(threads[i] ,NULL);
    }

    // Close the input file
    fclose(in_fp);

    // Close the output file
    fclose(out_fp);

    // Free the lock
    free(lock);

    // Free the threads
    free(threads);

    // Free the hash table
    free_hash_table(hash_table, HASH_TABLE_SIZE);

    return 0;
}

FILE* open_input_file() {

    FILE* fp = fopen("commands.txt", "r");

    if(!fp) {
        fprintf(stderr, "[ERROR]: Could not open commands.txt file\n");
        exit(1);
    }

    return fp;
}

FILE* open_output_file() {

    FILE* fp = fopen("output.txt", "w");

    if(!fp) {
        fprintf(stderr, "[ERROR]: Could not create or open the output.txt file\n");
        exit(1);
    }

    return fp;
}

line_t parse_line(char* buffer) {
    line_t line;

    // Get the command parameter
    char* token = strtok(buffer, ",");

    if(!token) {
        fprintf(stderr, "[ERROR]: Failed to tokenize input\n");
        exit(1);
    }

    line.command = strdup(token);

    // Get the parameter one
    token = strtok(NULL, ",");

    if(!token) {
        fprintf(stderr, "[ERROR]: Failed to tokenize input\n");
        exit(1);
    }

    line.param_one = strdup(token);

    // Get the parameter two
    token = strtok(NULL, ",");

    if(!token) {
        fprintf(stderr, "[ERROR]: Failed to tokenize input\n");
        exit(1);
    }

    line.param_two = strdup(token);

    return line;
}

void free_line(line_t line) {
    free(line.command);
    free(line.param_one);
    free(line.param_two);
}

pthread_t* allocate_threads(size_t num_threads) {
    pthread_t* threads = (pthread_t*)calloc(num_threads, sizeof(pthread_t));

    if(!threads) {
        fprintf(stderr, "[ERROR]: Could not allocate space for threads\n");
        exit(1);
    }

    return threads;
}

void* hash_table_thread_function(void* arg) {
    // Arguments
    thread_args_t* args = (thread_args_t*)arg;

    // Buffers
    char buffer[BUFFER_SIZE];
    line_t line;

    // Lock the file access
    pthread_mutex_lock(&file_mutex);

    // Read in the next line of the file
    fgets(buffer, BUFFER_SIZE, args->in_fp);
    line = parse_line(buffer);

    // Unlock the file access
    pthread_mutex_unlock(&file_mutex);

    // Perform correct operation
    if( !strcmp(line.command, "insert") ) {
        insert(args->hash_table, HASH_TABLE_SIZE, args->lock, line.param_one, atoi(line.param_two), args->out_fp);
    }
    else if( !strcmp(line.command, "delete") ) {
        // delete(args->hash_table, HASH_TABLE_SIZE, args->lock, line.param_one, args->out_fp);
    }
    else if( !strcmp(line.command, "search") ) {
        // search(args->hash_table, HASH_TABLE_SIZE, args->lock, line.param_one, args->out_fp);
    }
    else if( !strcmp(line.command, "print") ) {
        print(args->hash_table, HASH_TABLE_SIZE, args->lock, args->out_fp);
    }

    // Free line buffer
    free_line(line);

    return NULL;
}

#ifndef PROT_QUEUE_H
#define PROT_QUEUE_H

#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <string.h>
#include "cursor.h"

#define BUFFER_SIZE 100

/* 
 * The prot_queue structure represents a thread-safe queue that can hold generic data elements.
 */
struct prot_queue {
    unsigned char *buf;           // Buffer to hold the data elements.
    int buflen;                   // Length of the buffer.
    int head;                     // Index of the front of the queue.
    int tail;                     // Index of the end of the queue.
    int count;                    // Current count of elements in the queue.
    int elem_size;                // Size of each data element in the buffer.
    pthread_mutex_t mutex;        // Mutex to protect concurrent access.
    pthread_cond_t cond;          // Condition variable for synchronization.
};

/* 
 * Initialize the queue. 
 * Params:
 * q         - Pointer to the queue.
 * buf       - Buffer for holding data elements.
 * buflen    - Length of the buffer.
 * elem_size - Size of each data element.
 * Returns 1 if successful, 0 otherwise.
 */
static inline int prot_queue_init(struct prot_queue* q, void* buf, int buflen,
				  int elem_size)
{
    // Ensure buffer elements fit nicely in the buffer.
	if (buflen == 0 || buflen % elem_size != 0)
		return 0;

	q->head = 0;
	q->tail = 0;
	q->count = 0;
	q->buf = buf;
	q->buflen = buflen;
	q->elem_size = elem_size;

	pthread_mutex_init(&q->mutex, NULL);
	pthread_cond_init(&q->cond, NULL);

	return 1;
}

/* 
 * Return the capacity of the queue.
 * Params:
 * q - Pointer to the queue.
 */
static inline int prot_queue_capacity(struct prot_queue *q) {
	return q->buflen / q->elem_size;
}

/* 
 * Push an element onto the queue.
 * Params:
 * q    - Pointer to the queue.
 * data - Pointer to the data element to be pushed.
 * Returns 1 if successful, 0 if the queue is full.
 */
static inline int prot_queue_push(struct prot_queue* q, void *data)
{
	int cap;

	pthread_mutex_lock(&q->mutex);

	cap = prot_queue_capacity(q);
	if (q->count == cap) {
		pthread_mutex_unlock(&q->mutex);
		return 0;
	}

	memcpy(&q->buf[q->tail * q->elem_size], data, q->elem_size);
	q->tail = (q->tail + 1) % cap;
	q->count++;

	pthread_cond_signal(&q->cond);
	pthread_mutex_unlock(&q->mutex);

	return 1;
}

/* 
 * Try to pop an element from the queue without blocking.
 * Params:
 * q    - Pointer to the queue.
 * data - Pointer to where the popped data will be stored.
 * Returns 1 if successful, 0 if the queue is empty.
 */
static inline int prot_queue_try_pop(struct prot_queue *q, void *data) {
	pthread_mutex_lock(&q->mutex);

	if (q->count == 0) {
		pthread_mutex_unlock(&q->mutex);
		return 0;
	}

	memcpy(data, &q->buf[q->head * q->elem_size], q->elem_size);
	q->head = (q->head + 1) % prot_queue_capacity(q);
	q->count--;

	pthread_cond_signal(&q->cond);
	pthread_mutex_unlock(&q->mutex);
	return 1;
}

/* 
 * Pop an element from the queue. Blocks if the queue is empty.
 * Params:
 * q    - Pointer to the queue.
 * data - Pointer to where the popped data will be stored.
 */
static inline void prot_queue_pop(struct prot_queue *q, void *data) {
	pthread_mutex_lock(&q->mutex);

	while (q->count == 0)
		pthread_cond_wait(&q->cond, &q->mutex);

	memcpy(data, &q->buf[q->head * q->elem_size], q->elem_size);
	q->head = (q->head + 1) % prot_queue_capacity(q);
	q->count--;

	pthread_cond_signal(&q->cond);
	pthread_mutex_unlock(&q->mutex);
}

/* 
 * Destroy the queue. Releases resources associated with the queue.
 * Params:
 * q - Pointer to the queue.
 */
static inline void prot_queue_destroy(struct prot_queue* q) {
	pthread_mutex_destroy(&q->mutex);
	pthread_cond_destroy(&q->cond);
}

#endif // PROT_QUEUE_H

#include "prot_queue.h"
