#include <stdint.h>
#include "CH552.h"
#include "I2C.h"

void Wire_readRegister(uint8_t i2caddr, uint8_t regaddr, uint8_t *data, uint8_t bytes) {
    uint8_t status;

    // Set start condition and send device address with write bit
    I2C_Start();
    status = I2C_SendByte((i2caddr << 1) | 0x00);  // Write operation
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }

    // Send register address
    status = I2C_SendByte(regaddr);
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }

    // Set start condition again (repeated start) and send device address with read bit
    I2C_Start();
    status = I2C_SendByte((i2caddr << 1) | 0x01);  // Read operation
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }

    // Read bytes from I2C device
    while (bytes > 0) {
        if (bytes == 1) {
            *data = I2C_RecvByte(I2C_NACK);  // NACK after last byte
        } else {
            *data = I2C_RecvByte(I2C_ACK);
        }
        data++;
        bytes--;
    }

    // Set stop condition
    I2C_Stop();
}

#include <SoftI2C.h>

// Assume scl_pin and sda_pin are declared as extern in SoftI2C.h and initialized elsewhere
extern uint8_t scl_pin;
extern uint8_t sda_pin;

void Wire_readRegister(uint8_t i2caddr, uint8_t regaddr, uint8_t *data, uint8_t bytes) {
    uint8_t ack_bit;

    I2CStart();
    ack_bit = I2CSend((i2caddr << 1) | 0); // Write operation
    if (ack_bit != 0) {
        I2CStop();
        return;
    }

    // Send the register address from where data will be read
    ack_bit = I2CSend(regaddr);
    if (ack_bit != 0) {
        I2CStop();
        return;
    }

    I2CRestart();
    ack_bit = I2CSend((i2caddr << 1) | 1); // Read operation
    if (ack_bit != 0) {
        I2CStop();
        return;
    }

    // Read the specified number of bytes from the EEPROM
    for (uint8_t i = 0; i < bytes; i++) {
        data[i] = I2CRead();
        if (i == (bytes - 1)) {
            I2CNak();  // Send NAK after the last byte
        } else {
            I2CAck();  // Send ACK after reading a byte
        }
    }

    I2CStop();
}

