using namespace std;

// Function to convert a three-digit number to English words
string convertThreeDigits(int num) {
    // Arrays for one-digit, teens, and tens place values
    string ones[] = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"};
    string teens[] = {"", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
    string tens[] = {"", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};

    string result;

    // Extract digits
    int hundred = num / 100;
    int ten = (num % 100) / 10;
    int one = num % 10;

    // Convert hundreds place
    if (hundred > 0) {
        result += ones[hundred] + " Hundred ";
    }

    // Convert tens and ones place
    if (ten == 1) {
        result += teens[one] + " ";
    } else {
        if (ten > 1) {
            result += tens[ten] + " ";
        }
        if (one > 0) {
            result += ones[one] + " ";
        }
    }

    return result;
}

// Function to convert an integer to English words
string numberToWords(int num) {
    if (num == 0) {
        return "Zero";
    }

    // Arrays for scale place values
    string scale[] = {"", "Thousand", "Million", "Billion"};

    // Vector to store each group's English words
    vector<string> groups;

    int i = 0;
    while (num > 0) {
        int threeDigits = num % 1000;
        if (threeDigits != 0) {
            groups.push_back(convertThreeDigits(threeDigits) + scale[i]);
        }
        num /= 1000;
        i++;
    }

    // Combine the English phrases of each group
    string result;
    for (int j = groups.size() - 1; j >= 0; j--) {
        result += groups[j] + " ";
    }

    return result;
}

int main() {
    int num;
    cout << "Enter an integer: ";
    cin >> num;

    cout << "English phrase: " << numberToWords(num) << endl;

    return 0;
}

