// HashTable class
template <typename Key, typename Value>
class HashTable {
private:
    // HashNode class
    struct HashNode {
        Key key;
        Value value;
        HashNode(const Key& k, const Value& v) : key(k), value(v) {}
    };

    // Member variables
    std::vector<std::list<HashNode>> buckets;
    size_t numBuckets;

    // Hash function
    size_t hash(const Key& key) const {
        return std::hash<Key>{}(key) % numBuckets;
    }

public:
    // Constructor
    HashTable(size_t size = 10) : numBuckets(size), buckets(size) {}

    // Insert key-value pair into the hash table
    void insert(const Key& key, const Value& value) {
        size_t index = hash(key);
        for (const auto& node : buckets[index]) {
            if (node.key == key) {
                std::cout << "Key already exists. Updating value." << std::endl;
                const_cast<Value&>(node.value) = value;  // Update existing value
                return;
            }
        }
        buckets[index].emplace_back(key, value);
    }

    // Retrieve value associated with a key
    Value get(const Key& key) const {
        size_t index = hash(key);
        for (const auto& node : buckets[index]) {
            if (node.key == key) {
                return node.value;
            }
        }
        throw std::out_of_range("Key not found in hash table.");
    }

    // Remove a key-value pair from the hash table
    void remove(const Key& key) {
        size_t index = hash(key);
        for (auto it = buckets[index].begin(); it != buckets[index].end(); ++it) {
            if (it->key == key) {
                buckets[index].erase(it);
                return;
            }
        }
        throw std::out_of_range("Key not found in hash table.");
    }

    // Check if a key exists in the hash table
    bool contains(const Key& key) const {
        size_t index = hash(key);
        for (const auto& node : buckets[index]) {
            if (node.key == key) {
                return true;
            }
        }
        return false;
    }
};

// Test the HashTable class
int main() {
    HashTable<std::string, int> myHashTable(5);
    myHashTable.insert("one", 1);
    myHashTable.insert("two", 2);
    myHashTable.insert("three", 3);

    std::cout << "Value associated with 'two': " << myHashTable.get("two") << std::endl;

    myHashTable.remove("two");

    if (myHashTable.contains("two")) {
        std::cout << "Found key 'two' in the hash table." << std::endl;
    } else {
        std::cout << "Key 'two' not found in the hash table." << std::endl;
    }

    return 0;
}

