#include <vector>

using namespace std;

struct Person {
    int birth;
    int death;
};

int findMostAliveYear(const vector<Person>& people) {
    // Initialize an array to represent the range of years between 1900 and 2000
    int years[101] = {0};  // Assuming 1900 to 2000, so 101 years in total

    // Iterate through each person and update the count for each year of their life
    for (const Person& p : people) {
        for (int year = p.birth; year <= p.death; ++year) {
            years[year - 1900]++;
        }
    }

    // Find the year with the highest count
    int maxAliveYear = 1900;
    int maxAliveCount = years[0];

    for (int i = 1; i < 101; ++i) {
        if (years[i] > maxAliveCount) {
            maxAliveCount = years[i];
            maxAliveYear = 1900 + i;
        }
    }

    return maxAliveYear;
}

int main() {
    // Example usage
    vector<Person> people = {
        {1900, 1950},
        {1910, 1930},
        {1920, 1970},
        // Add more people as needed
    };

    int mostAliveYear = findMostAliveYear(people);

    cout << "The year with the most people alive is: " << mostAliveYear << endl;

    return 0;
}

#include <unordered_map>
#include <list>

using namespace std;

class LRUCache {
private:
    int capacity;
    unordered_map<int, pair<int, list<int>::iterator>> cache;  // Map to store key-value pairs along with their positions in the list
    list<int> lruList;  // Doubly linked list to keep track of the least recently used items

public:
    LRUCache(int capacity) {
        this->capacity = capacity;
    }

    int get(int key) {
        auto it = cache.find(key);

        // If the key is not in the cache, return -1
        if (it == cache.end()) {
            return -1;
        }

        // Move the accessed item to the front of the list
        lruList.erase(it->second.second);
        lruList.push_front(key);

        // Update the iterator in the cache map
        it->second.second = lruList.begin();

        // Return the value associated with the key
        return it->second.first;
    }

    void put(int key, int value) {
        auto it = cache.find(key);

        // If the key is already in the cache, update its value and move it to the front of the list
        if (it != cache.end()) {
            lruList.erase(it->second.second);
        }

        // If the cache is full, evict the least recently used item
        if (cache.size() == capacity) {
            int lruKey = lruList.back();
            lruList.pop_back();
            cache.erase(lruKey);
        }

        // Insert the new key-value pair and update the list
        lruList.push_front(key);
        cache[key] = {value, lruList.begin()};
    }
};

int main() {
    // Example usage
    LRUCache cache(2);  // Initialize with capacity 2

    cache.put(1, 1);
    cache.put(2, 2);
    cout << cache.get(1) << endl;  // Output: 1
    cache.put(3, 3);  // evicts key 2
    cout << cache.get(2) << endl;  // Output: -1 (not found)
    cache.put(4, 4);  // evicts key 1
    cout << cache.get(1) << endl;  // Output: -1 (not found)
    cout << cache.get(3) << endl;  // Output: 3
    cout << cache.get(4) << endl;  // Output: 4
    return 0;
}

