int addWithoutPlus(int a, int b) {
    while (b != 0) {
        // Calculate the carry
        int carry = a & b;

        // XOR operation to get the sum without carry
        a = a ^ b;

        // Shift the carry to the left by 1 position
        b = carry << 1;
    }

    return a;
}

