class BiNode {
public:
    BiNode* node1;
    BiNode* node2;
    int data;

    BiNode(int value) : data(value), node1(nullptr), node2(nullptr) {}
};

class BinaryTreeToDoublyLinkedList {
public:
    static BiNode* convertBSTToDLL(BiNode* root) {
        BiNode* head = nullptr;
        BiNode* prev = nullptr;

        convertBSTToDLLHelper(root, head, prev);

        return head;
    }

private:
    static void convertBSTToDLLHelper(BiNode* root, BiNode*& head, BiNode*& prev) {
        if (root == nullptr) {
            return;
        }

        // Recursively convert the left subtree
        convertBSTToDLLHelper(root->node1, head, prev);

        // Process the current node
        if (prev == nullptr) {
            // If prev is null, this is the leftmost node (head of the DLL)
            head = root;
        } else {
            // Make the right pointer of the previous node point to the current node
            prev->node2 = root;
            // Make the left pointer of the current node point to the previous node
            root->node1 = prev;
        }

        // Update prev to the current node
        prev = root;

        // Recursively convert the right subtree
        convertBSTToDLLHelper(root->node2, head, prev);
    }
};

// Helper function to print the doubly linked list
void printDoublyLinkedList(BiNode* head) {
    while (head != nullptr) {
        std::cout << head->data << " ";
        head = head->node2; // Move to the next node
    }
    std::cout << std::endl;
}

