#include <iostream>
#include <stack>

class BiNode {
public:
    BiNode* node1;
    BiNode* node2;
    int data;

    BiNode(int value) : data(value), node1(nullptr), node2(nullptr) {}
};

class BinaryTreeToDoublyLinkedList {
public:
    static BiNode* convertBSTToDLL(BiNode* root) {
        if (root == nullptr) {
            return nullptr;
        }

        BiNode* head = nullptr;
        BiNode* prev = nullptr;

        std::stack<BiNode*> stack;

        while (root != nullptr || !stack.empty()) {
            while (root != nullptr) {
                stack.push(root);
                root = root->node1;
            }

            root = stack.top();
            stack.pop();

            if (prev == nullptr) {
                // If prev is null, this is the leftmost node (head of the DLL)
                head = root;
            } else {
                // Make the right pointer of the previous node point to the current node
                prev->node2 = root;
                // Make the left pointer of the current node point to the previous node
                root->node1 = prev;
            }

            // Update prev to the current node
            prev = root;

            // Move to the right subtree
            root = root->node2;
        }

        return head;
    }
};

// Helper function to print the doubly linked list
void printDoublyLinkedList(BiNode* head) {
    while (head != nullptr) {
        std::cout << head->data << " ";
        head = head->node2; // Move to the next node
    }
    std::cout << std::endl;
}

int main() {
    // Example usage:
    BiNode* root = new BiNode(4);
    root->node1 = new BiNode(2);
    root->node2 = new BiNode(5);
    root->node1->node1 = new BiNode(1);
    root->node1->node2 = new BiNode(3);

    BiNode* head = BinaryTreeToDoublyLinkedList::convertBSTToDLL(root);

    std::cout << "Doubly Linked List: ";
    printDoublyLinkedList(head);

    // Clean up the memory (you might want to implement a destructor for BiNode for real-world scenarios)
