// Define the GPIO pin for the LED
const int ledPin = 18;

// Command words
const char* commands[] = {"on", "off"};

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);

  // Initialize Skainet
  esp_skainet_init();

  // Register command words
  esp_skainet_add_command(commands[0], 1); // Command ID for "on"
  esp_skainet_add_command(commands[1], 2); // Command ID for "off"

  // Start voice recognition
  esp_skainet_start();
}

