// Function to find the begin iterator of the sequence with leading whitespace stripped
template<typename Iterator>
Iterator find_begin(Iterator begin, Iterator end) {
    while (begin != end && std::isspace(*begin)) {
        ++begin;
    }
    return begin;
}

// Function to find the end iterator of the sequence with trailing whitespace stripped
template<typename Iterator>
Iterator find_end(Iterator begin, Iterator end) {
    while (begin != end && std::isspace(*(end - 1))) {
        --end;
    }
    return end;
}

int main() {
    // Example usage
    std::string str = "   Hello, world!   ";

    // Find begin and end iterators with leading and trailing whitespace stripped
    auto begin = find_begin(str.begin(), str.end());
    auto end = find_end(str.begin(), str.end());

    // Output the stripped sequence
    for (auto it = begin; it != end; ++it) {
        std::cout << *it;
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

// Function to find the begin iterator of the sequence with leading whitespace stripped
template<typename Iterator>
Iterator find_begin(Iterator begin, Iterator end) {
    return std::find_if_not(begin, end, [](char c) { return std::isspace(c); });
}

// Function to find the end iterator of the sequence with trailing whitespace stripped
template<typename Iterator>
Iterator find_end(Iterator begin, Iterator end) {
    return std::find_if_not(std::make_reverse_iterator(end), std::make_reverse_iterator(begin), [](char c) { return std::isspace(c); }).base();
}

int main() {
    std::string text = "   Hello, world!   ";
    auto begin = find_begin(text.begin(), text.end());
    auto end = find_end(text.begin(), text.end());
    std::string stripped_text(begin, end);
    std::cout << "Stripped text: '" << stripped_text << "'" << std::endl;
    return 0;
}

#include <signal.h>
#include <stdlib.h>
#include <unistd.h>

void signal_handler(int signum) {
    // Exit with a non-zero code if called more than once, indicating SA_RESETHAND didn't work
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    pid_t pid;

    // Setup the signal handler
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESETHAND; // Reset the signal handler to default after first delivery
    sigemptyset(&sa.sa_mask);

    // Set the action for SIGINT
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        exit(EXIT_FAILURE); // Exit with a non-zero code if sigaction fails
    }

    pid = fork();
    if (pid == -1) {
        // Fork failed
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        sleep(1); // Wait for 1 second before sending the signal
        kill(getppid(), SIGINT); // Send SIGINT to parent process
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        pause(); // Wait for the signal

        // If the program reaches this point, it means the signal handler wasn't triggered.
        // This is a failure in this context.
        exit(EXIT_FAILURE);
    }
}

